#!/usr/bin/env python3
"""Differential fuzz: submission vs literal reference."""
import json
import subprocess
import sys
import os

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import gen as G

SUB = ["python3", "/workspace/submission/main.py"]
REF = ["python3", "/workspace/tmp/ref.py"]


def runone(cmd, text):
    p = subprocess.run(cmd, input=text.encode(), capture_output=True)
    return p.returncode, p.stdout, p.stderr


def diff_report(a, b, path=""):
    out = []
    if type(a) != type(b):
        out.append("%s type %r vs %r" % (path, type(a), type(b)))
        return out
    if isinstance(a, dict):
        for k in sorted(set(a) | set(b)):
            if k not in a or k not in b:
                out.append("%s.%s missing" % (path, k))
            else:
                out += diff_report(a[k], b[k], path + "." + k)
    elif isinstance(a, list):
        if len(a) != len(b):
            out.append("%s len %d vs %d" % (path, len(a), len(b)))
        else:
            for i, (x, y) in enumerate(zip(a, b)):
                out += diff_report(x, y, "%s[%d]" % (path, i))
    else:
        if a != b:
            out.append("%s %r vs %r" % (path, a, b))
    return out


def main():
    lo = int(sys.argv[1]); hi = int(sys.argv[2])
    big = len(sys.argv) > 3 and sys.argv[3] == "big"
    bad = 0
    for seed in range(lo, hi):
        doc = G.gen(seed, big)
        text = json.dumps(doc)
        rc1, o1, e1 = runone(SUB, text)
        rc2, o2, e2 = runone(REF, text)
        if rc1 != 0 or rc2 != 0:
            print("seed", seed, "rc", rc1, rc2); bad += 1; continue
        try:
            j1 = json.loads(o1)
            j2 = json.loads(o2)
        except Exception as ex:
            print("seed", seed, "unparsable", ex, o1[:200], o2[:200]); bad += 1
            continue
        if j1 != j2:
            bad += 1
            print("=== seed", seed, "DIFF ===")
            d = diff_report(j1, j2)
            for line in d[:25]:
                print("   ", line)
            open("/workspace/tmp/fail_%d.json" % seed, "w").write(
                json.dumps(doc, indent=1))
            if bad >= 3:
                break
    print("checked", hi - lo, "seeds; mismatches:", bad)


if __name__ == "__main__":
    main()
